package dev.veil.detect;

import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Accuracy on a labelled set of ~500 realistic prompts with planted values and decoys
 * (src/test/resources/eval, generated by generate.py). Fails the build if any detector falls below its
 * precision or recall target, and writes a report to target/detection-eval.md.
 */
class DetectionEvalTest {

    /** Findings below the recommended policy's threshold don't count: that's what users experience. */
    private static final double POLICY_THRESHOLD = 0.7;
    private static final Set<EntityType> LOOSER = Set.of(EntityType.PERSON);

    record Label(EntityType type, String value) {
    }

    record Counts(int[] tp, int[] fp, int[] fn) {
    }

    @Test
    void precisionAndRecallPerDetector() throws IOException {
        List<String> lines;
        try (InputStream in = getClass().getResourceAsStream("/eval/eval.tsv")) {
            lines = new String(in.readAllBytes(), StandardCharsets.UTF_8).lines().toList();
        }
        ScanEngine engine = ScanEngine.standard();
        Map<EntityType, int[]> stats = new EnumMap<>(EntityType.class); // tp, fp, fn
        List<String> mistakes = new ArrayList<>();
        long micros = 0;

        for (String line : lines) {
            String[] parts = line.split("\t", -1);
            String text = parts[0];
            List<Label> labels = new ArrayList<>();
            if (parts.length > 1 && !parts[1].isBlank()) {
                for (String l : parts[1].split("\\|\\|")) {
                    int eq = l.indexOf('=');
                    labels.add(new Label(EntityType.valueOf(l.substring(0, eq)), l.substring(eq + 1)));
                }
            }
            ScanResult result = engine.scan(text);
            micros += result.totalMicros();
            List<Finding> found = result.findings().stream()
                    .filter(f -> f.type().spanBased() && f.confidence() >= POLICY_THRESHOLD).toList();
            List<Label> unmatched = new ArrayList<>(labels);
            for (Finding f : found) {
                Label hit = unmatched.stream().filter(l -> l.type() == f.type() && sameValue(l.value(), f.value()))
                        .findFirst().orElse(null);
                int[] s = stats.computeIfAbsent(f.type(), k -> new int[3]);
                if (hit != null) {
                    s[0]++;
                    unmatched.remove(hit);
                } else {
                    s[1]++;
                    mistakes.add("FP " + f.type() + " '" + f.value() + "' in: " + text);
                }
            }
            for (Label l : unmatched) {
                stats.computeIfAbsent(l.type(), k -> new int[3])[2]++;
                mistakes.add("FN " + l.type() + " '" + l.value() + "' in: " + text);
            }
        }

        StringBuilder report = new StringBuilder("# Detection evaluation\n\n")
                .append(lines.size()).append(" prompts, average scan time ")
                .append(String.format("%.0f µs", (double) micros / lines.size())).append("\n\n")
                .append("| Type | TP | FP | FN | Precision | Recall |\n|---|---|---|---|---|---|\n");
        stats.forEach((type, s) -> report.append(String.format("| %s | %d | %d | %d | %.3f | %.3f |%n",
                type, s[0], s[1], s[2], precision(s), recall(s))));
        report.append("\n## Mistakes\n\n");
        mistakes.forEach(m -> report.append("- ").append(m.replace("\n", " ")).append('\n'));
        Path out = Path.of("target", "detection-eval.md");
        Files.createDirectories(out.getParent());
        Files.writeString(out, report);
        System.out.println(report);

        stats.forEach((type, s) -> {
            double minP = LOOSER.contains(type) ? 0.90 : 0.95;
            double minR = LOOSER.contains(type) ? 0.85 : 0.90;
            assertThat(precision(s)).as("precision of " + type).isGreaterThanOrEqualTo(minP);
            assertThat(recall(s)).as("recall of " + type).isGreaterThanOrEqualTo(minR);
        });
    }

    private static boolean sameValue(String expected, String found) {
        String e = expected.strip();
        String f = found.strip();
        return e.equals(f) || (f.contains(e) && f.length() <= e.length() + 2) || (e.contains(f) && f.length() >= e.length() - 2);
    }

    private static double precision(int[] s) {
        return s[0] + s[1] == 0 ? 1 : (double) s[0] / (s[0] + s[1]);
    }

    private static double recall(int[] s) {
        return s[0] + s[2] == 0 ? 1 : (double) s[0] / (s[0] + s[2]);
    }
}
